{"filename":"script.js","content":"(function(){
  const API_BASE = '/api';
  const pages = {};

  // Simple toast notifications
  function showToast(message, type='info'){
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.textContent = message;
    document.body.appendChild(toast);
    setTimeout(()=>{ toast.remove(); }, 3000);
  }

  // Wrapper for fetch API
  async function api(path, options={}){
    const resp = await fetch(API_BASE + path, Object.assign({headers:{'Content-Type':'application/json'}}, options));
    if(!resp.ok){
      const err = await resp.json().catch(()=>({error:'Unexpected error'}));
      throw new Error(err.error || resp.statusText);
    }
    return resp.json();
  }

  // Page registration API
  window.ForgeAI = window.ForgeAI || {};
  window.ForgeAI.registerPage = function(slug, renderer){
    pages[slug] = renderer;
  };

  // Resolve root element for page content
  function getPageRoot(){
    let root = document.getElementById('page-root');
    if(!root){
      root = document.createElement('div');
      root.id = 'page-root';
      const app = document.getElementById('app');
      // Insert after sidebar (first child after aside)
      const aside = app.querySelector('aside');
      if(aside){
        aside.insertAdjacentElement('afterend', root);
      } else {
        app.appendChild(root);
      }
    }
    return root;
  }

  // Render the current hash route
  async function renderRoute(){
    const hash = location.hash || '#/dashboard';
    const slug = hash.replace(/^#\/?/, '').split('?')[0];
    const root = getPageRoot();
    root.innerHTML = '<div class="loading">Loading…</div>';
    const renderer = pages[slug];
    if(renderer){
      try{
        await renderer({root, api, showToast});
      }catch(e){
        root.innerHTML = `<p class="error">${e.message}</p>`;
        console.error(e);
      }
    } else {
      root.innerHTML = '<p>Page not found.</p>';
    }
  }

  window.addEventListener('hashchange', renderRoute);
  window.addEventListener('load', renderRoute);

  // ---------- Default Pages ---------- //

  // Dashboard page
  window.ForgeAI.registerPage('dashboard', async ({root, api, showToast})=>{
    root.innerHTML = `
      <section class="dashboard">
        <h2 class="page-title">Dashboard</h2>
        <div class="kpi-grid" id="kpi-grid"></div>
        <h3>Recent Sessions</h3>
        <ul class="activity-list" id="recent-list"></ul>
        <h3>Activity Over Time</h3>
        <canvas id="activity-chart" width="600" height="300"></canvas>
      </section>`;

    // Fetch KPI data
    const data = await api('/dashboard'); // expected shape {kpis:[{label, value}], recent_sessions:[{id, workout_title, date, calories}] 
    // Render KPI cards
    const kpiGrid = root.querySelector('#kpi-grid');
    data.kpis.forEach(k=>{
      const card = document.createElement('div');
      card.className = 'kpi-card';
      card.innerHTML = `<div class="kpi-label">${k.label}</div><div class="kpi-value">${k.value}</div>`;
      kpiGrid.appendChild(card);
    });

    // Render recent activity list
    const recentList = root.querySelector('#recent-list');
    if(data.recent_sessions.length===0){
      recentList.innerHTML = '<li>No sessions recorded yet.</li>';
    }else{
      data.recent_sessions.forEach(s=>{
        const li = document.createElement('li');
        li.className = 'activity-item';
        li.textContent = `${s.date}: ${s.workout_title} – ${s.duration_minutes} min, ${s.calories_burned} kcal`;
        recentList.appendChild(li);
      });
    }

    // Simple line chart using Canvas API
    const canvas = root.querySelector('#activity-chart');
    if(canvas && data.session_trends && data.session_trends.length>1){
      const ctx = canvas.getContext('2d');
      const w = canvas.width; const h = canvas.height;
      const padding = 40;
      const points = data.session_trends.map(p=>({x:new Date(p.date), y:p.calories_burned}));
      const xs = points.map(p=>p.x.getTime());
      const ys = points.map(p=>p.y);
      const xMin = Math.min(...xs), xMax = Math.max(...xs);
      const yMin = Math.min(...ys), yMax = Math.max(...ys);
      function xScale(t){ return padding + (t - xMin) / (xMax - xMin) * (w - 2*padding); }
      function yScale(v){ return h - padding - (v - yMin) / (yMax - yMin) * (h - 2*padding); }
      ctx.clearRect(0,0,w,h);
      ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue('--accent-colour') || '#336699';
      ctx.lineWidth = 2;
      ctx.beginPath();
      points.forEach((p,i)=>{
        const x = xScale(p.x.getTime());
        const y = yScale(p.y);
        if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
      });
      ctx.stroke();
      // Axes
      ctx.strokeStyle = '#ccc';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, h - padding);
      ctx.lineTo(w - padding, h - padding);
      ctx.stroke();
    }
  });

  // Settings page (basic profile persistence)
  window.ForgeAI.registerPage('settings', async ({root, api, showToast})=>{
    root.innerHTML = `
      <section class="settings">
        <h2 class="page-title">Settings</h2>
        <form id="settings-form">
          <label>
            Username:
            <input type="text" name="username" required />
          </label>
          <label>
            Preferred Accent Colour:
            <input type="color" name="accent_colour" value="#336699" />
          </label>
          <button type="submit">Save</button>
        </form>
      </section>`;
    const form = root.querySelector('#settings-form');
    // Load existing settings if any
    try{
      const profile = await api('/profile'); // assume endpoint exists, fallback to defaults if 404
      form.username.value = profile.username || '';
      form.accent_colour.value = profile.accent_colour || '#336699';
    }catch(e){ /* ignore */ }
    form.addEventListener('submit', async e=>{
      e.preventDefault();
      const payload = {
        username: form.username.value.trim(),
        accent_colour: form.accent_colour.value
      };
      try{
        await api('/profile', {method:'POST', body:JSON.stringify(payload)});
        showToast('Settings saved', 'success');
        // Apply new accent colour dynamically
        document.documentElement.style.setProperty('--accent-colour', payload.accent_colour);
      }catch(err){
        showToast('Failed to save settings: '+err.message, 'error');
      }
    });
  });

})();"}
